@lru_cache(maxsize=None)
def min_coins(amount, coins):
    if amount == 0:
        return 0
    if amount < 0:
        return -1
    best = -1
    for c in coins:
        res = min_coins(amount - c, coins)
        if res >= 0:
            if best == -1 or res + 1 < best:
                best = res + 1
    return best
